# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def printTree(self, root: TreeNode) -> List[List[str]]:
        def height(node):
            if not node:
                return 0
            return 1 + max(height(node.left), height(node.right))

        h = height(root)
        m, n = h, 2 ** h - 1
        ans = [[""] * n for _ in range(m)]

        def dfs(node, r, c):
            if not node:
                return
            ans[r][c] = str(node.val)
            dfs(node.left, r + 1, c - (n // 2 ** (h - r - 1)))
            dfs(node.right, r + 1, c + (n // 2 ** (h - r - 1)))

        dfs(root, 0, n // 2)
        return ans
```
